#!/usr/bin/bash

function _lock_dir() {
	if [[ -d $1 ]]; then
		chattr +i "$1" || true
	fi
}

function _systemd_enable_execute() {
	local SERVICE=$1 TYPE=$2 WHO_AM_I OUT_DIR

	WHO_AM_I="$(realpath "${BASH_SOURCE[0]}")"
	OUT_DIR="/entrypoint/systemd.enables.d"

	local SUCC_OVERRIDE="/etc/systemd/system/success.service.d/enable.conf"
	local NOTIFY_OVERRIDE="/etc/systemd/system/notify-stop.service.d/enable.conf"

	mkdir -p "$(dirname "${SUCC_OVERRIDE}")" "$(dirname "${NOTIFY_OVERRIDE}")"

	if ! [[ -e ${SUCC_OVERRIDE} ]]; then
		echo "[Unit]
# Generated by ${WHO_AM_I}
" >"${SUCC_OVERRIDE}"
	fi
	if ! [[ -e ${NOTIFY_OVERRIDE} ]]; then
		echo "[Unit]
# Generated by ${WHO_AM_I}
" >"${NOTIFY_OVERRIDE}"
	fi

	local REQUIRES_FILES=() WANTS_FILES=() FILE
	walk_dir REQUIRES_FILES "${OUT_DIR}/requires"
	walk_dir WANTS_FILES "${OUT_DIR}/wants"

	_lock_dir "${OUT_DIR}/requires"
	_lock_dir "${OUT_DIR}/wants"

	{
		# 向 success.service 添加 Requires/Wants
		for FILE in "${REQUIRES_FILES[@]}"; do
			echo "Requires=${FILE}"
		done
		for FILE in "${WANTS_FILES[@]}"; do
			echo "Wants=${FILE}"
		done
	} >>"${SUCC_OVERRIDE}"

	{
		# 向 notify-stop.service 添加 After
		for FILE in "${REQUIRES_FILES[@]}" "${WANTS_FILES[@]}"; do
			echo "After=${FILE}"
		done
	} >>"${NOTIFY_OVERRIDE}"
}

_systemd_enable_execute
